"""Frozen 9CM edge coverage, current reviewed blocks, no LR association tests."""
from pathlib import Path
from datetime import datetime,timezone
import os,json,hashlib
import numpy as np,pandas as pd

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 start=datetime.now(timezone.utc).isoformat();R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);B=AR/'20261010_expression_annotation_downstream_v1';P=R/'immune_same_name_family_source_review_v1';U=P/'patient_block_provenance_overlay_v1';O=P/'CM_edge_coverage_v1';planpath=Path(os.environ['PANCANCER_CM_COVERAGE_PLAN']);plan=json.loads(planpath.read_text());assert not O.exists();assert sha(__file__)==plan['code_sha256'][Path(__file__).name]
 paths=dict(edges=B/'downstream_review_v2/corrected_CM_edges_source_and_marker_evidence.tsv',counts=B/'inputs/sample_major_subcluster_counts.tsv',sample_metadata=B/'inputs/sample_metadata.tsv',W=B/'covarnet/tables/nmf_W_subcluster_by_cm.tsv',H=B/'covarnet/tables/nmf_H_cm_by_sample.tsv',F=B/'covarnet/tables/frequency_normalized.tsv',catalogue=B/'downstream_review_v2/number_to_annotation_dictionary.tsv',liana_status=B/'liana/sample_status.tsv',liana_audit=B/'liana/independent_audit.json',provenance_inventory=U/'inventory.json',provenance_audit=U/'independent_audit.json',provenance_scope=U/'private_all1290_patient_provenance_overlay.tsv')
